[ -d /var/lib/morpheus-certificate-install/runs ] && find /var/lib/morpheus-certificate-install/runs -maxdepth 1 -type f -name '*.sh' -printf 'script|%p|%s|%T@\n'; [ -d /var/log/morpheus-certificate-install ] && find /var/log/morpheus-certificate-install -maxdepth 1 -type f \( -name '*.log' -o -name '*.rc' \) -printf 'log|%p|%s|%T@\n'; [ -d /var/lib/morpheus-certificate-install/backups ] && for d in /var/lib/morpheus-certificate-install/backups/*/; do [ -d "$d" ] || continue; d=${d%/}; printf 'backup|%s|%s|%s|%s\n' "$d" "$(du -sb "$d" | cut -f1)" "$(stat -c %Y "$d")" "$(find "$d" -type f -name '*.key' | wc -l)"; done; true
